mapper.select:
select pro.P_Name as pName, pro.P_Code as pCode, con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, proc.C_Name as pConstructionUnitName, proc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompetentDepartmentName, qt.Qst_Name as qstName, qt.Qst_Code as qstCode, qt.Qst_Item as qstItem, c1.C_Name as qsrDutyCpyName, c2.C_Name as ptContractorName, c3.C_Name as ptSupervisorName, u1.U_Name as rectifyUname, mn.Pt_Code as ptCode, mn.Pt_Measure as ptMeasure, mn.Pt_Type as ptType, mn.Pt_Category as ptCategory, mn.Pt_Pitfall as ptPitfall, mn.Pt_Evaluation_Time as ptEvaluationTime, mn.Pt_Group_Member_Name as ptGroupMemberName, mn.Pt_Description as ptDescription, mn.Pt_Rectify_Require_Time as ptRectifyRequireTime, qr.* from Qs_Record qr left join Qs_Type qt on qt.Qst_Id = qr.Qst_Id left join SYS_Company c1 on c1.C_Id = qr.Qsr_Duty_Cpy left join Sys_User u1 on u1.U_Id = qr.Qsr_Rectify_Uid left join Qs_Plan_Task mn on mn.id=qr.Pt_Id left join SYS_Company c2 on c2.C_Id = mn.Pt_Contractor_Id left join SYS_Company c3 on c3.C_Id = mn.Pt_Supervisor_Id left join Con_Contract con on con.Con_Id = mn.Con_Id left join Pre_Project pro on pro.P_Id = mn.P_Id left join SYS_Company proc on proc.C_Id = pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id = pro.P_Competent_Department
and qr.Pt_Id in
#{ptId}
and qr.Qsr_Id in
#{ptId}

select mn.Pt_Code as ptCode, pro.P_Name as pName, mn.Pt_Type as ptType, mn.Pt_Group_Member_Name as ptGroupMemberName, mn.Pt_Evaluation_Time as ptEvaluationTime, qr.qsr_Rectify_Require_Time as qsrRectifyRequireTime, qr.qsr_Rectify_Status as qsrRectifyStatus, mn.state as state from Qs_Record qr left join Qs_Type qt on qt.Qst_Id = qr.Qst_Id left join Qs_Plan_Task mn on mn.id=qr.Pt_Id left join Pre_Project pro on pro.P_Id = mn.P_Id
mn.state != 3 and mn.state != 0 and qr.qsr_Rectify_Status != '03'
and mn.pt_Category = #{params.ptCategory}
and mn.state = #{params.state}
and mn.Pt_Code = #{params.ptCode}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and mn.Pt_Group_Member_Name like concat('%',#{params.ptGroupMemberName},'%')
and mn.Pt_Type = #{params.ptType}
AND mn.Pt_Evaluation_Time > #{params.ptEvaluationTimeStr}
AND mn.Pt_Evaluation_Time < #{params.ptEvaluationTimeEnd}
AND mn.Pt_Evaluation_Time BETWEEN #{params.ptEvaluationTimeStr} AND #{params.ptEvaluationTimeEnd}
